"""Presentation-only bridge to the supplied live replay."""
import streamlit as st
from simulation_dashboard import render

LIVE_CSS = '<style>.st-key-updated_live { --void:#101214; --panel:#101214; --line:#2a2e33; --ice:#e8eaec; --cyan:#a9c4d4; --mint:#a9c4d4; --amber:#c5d6a0; --red:#d78b80; --muted:#9aa0a6; }\n        .st-key-updated_live .cockpit-head{ display:flex; align-items:flex-end; justify-content:space-between; gap:1rem; margin-bottom:.65rem; }\n        .st-key-updated_live .brand{ font:600 .69rem \'Arial\'; letter-spacing:.22em; color:var(--cyan); text-transform:uppercase; }\n        .st-key-updated_live .title{ font:700 2.15rem/1 \'Arial\'; letter-spacing:.01em; color:var(--ice); margin:.22rem 0 .16rem; }\n        .st-key-updated_live .subtitle{ font-size:.82rem; color:var(--muted); }\n        .st-key-updated_live .live-pill{ display:flex; align-items:center; gap:.5rem; border:1px solid #2a2e33; background:#101214; padding:.42rem .68rem; font:600 .67rem \'Arial\'; letter-spacing:.08em; color:var(--cyan); }\n        .st-key-updated_live .live-dot{ width:7px; height:7px; border-radius:50%; background:var(--cyan); box-shadow:0 0 12px var(--cyan); animation:pulse 1.25s infinite; }\n        @keyframes pulse { 50% { opacity:.35; transform:scale(.72); } }\n        .st-key-updated_live .control-rail{ border:1px solid var(--line); background:rgba(23,25,27,.88); padding:.55rem .7rem; margin-bottom:.7rem; }\n        .st-key-updated_live [data-testid="stButton"] button{ width:100%; min-height:2.15rem; border:1px solid #2a2e33 !important; border-radius:2px; background:#101214 !important; color:var(--ice) !important; font:600 .72rem \'Arial\'; }\n        .st-key-updated_live [data-testid="stButton"] button:hover{ border-color:var(--cyan) !important; color:var(--cyan) !important; }\n        .st-key-updated_live [data-testid="stButton"] button:focus-visible{ outline:2px solid var(--cyan); outline-offset:2px; }\n        .st-key-updated_live .clock{ height:100%; display:flex; flex-direction:column; justify-content:center; border-left:1px solid var(--line); padding-left:1rem; }\n        .st-key-updated_live .clock strong{ font:600 1.25rem \'Arial\'; color:var(--ice); }\n        .st-key-updated_live .clock span{ font:500 .61rem \'Arial\'; letter-spacing:.12em; color:var(--muted); text-transform:uppercase; }\n        .st-key-updated_live .kpi-grid{ display:grid; grid-template-columns:repeat(4,1fr); gap:.6rem; margin-bottom:.7rem; }\n        .st-key-updated_live .kpi{ position:relative; overflow:hidden; min-height:74px; padding:.68rem .78rem; border:1px solid var(--line); background:linear-gradient(135deg, rgba(15,16,18,.96), rgba(8,9,10,.96)); }\n        .st-key-updated_live .kpi:after{ content:\'\'; position:absolute; inset:auto 0 0; height:2px; background:var(--accent,var(--cyan)); box-shadow:0 0 14px var(--accent,var(--cyan)); }\n        .st-key-updated_live .k-label{ font:500 .59rem \'Arial\'; letter-spacing:.13em; color:var(--muted); text-transform:uppercase; }\n        .st-key-updated_live .k-value{ font:700 1.72rem/1 \'Arial\'; color:var(--ice); margin:.28rem 0 .15rem; }\n        .st-key-updated_live .k-note{ font-size:.67rem; color:var(--muted); }\n        .st-key-updated_live .panel{ border:1px solid var(--line); background:rgba(8,9,10,.90); padding:.7rem; }\n        .st-key-updated_live .panel-label{ font:600 .62rem \'Arial\'; color:var(--muted); letter-spacing:.14em; text-transform:uppercase; margin-bottom:.35rem; }\n        .st-key-updated_live .engine-core{ display:grid; place-items:center; min-height:162px; position:relative; overflow:hidden; }\n        .st-key-updated_live .engine-core:before{ content:\'\'; position:absolute; width:245px; height:245px; border:1px solid rgba(169,174,180,.12); border-radius:50%; box-shadow:0 0 0 30px rgba(169,174,180,.02),0 0 0 60px rgba(169,174,180,.015); }\n        .st-key-updated_live .health-ring{ --score:80; --ring:var(--cyan); width:138px; height:138px; display:grid; place-items:center; border-radius:50%; background:conic-gradient(var(--ring) calc(var(--score)*1%), #282b2e 0); filter:drop-shadow(0 0 16px rgba(169,174,180,.18)); }\n        .st-key-updated_live .health-ring:before{ content:\'\'; position:absolute; width:116px; height:116px; border-radius:50%; background:#101214; border:1px solid #3a3e43; }\n        .st-key-updated_live .health-copy{ position:relative; z-index:2; text-align:center; }\n        .st-key-updated_live .health-copy strong{ display:block; font:700 2.3rem/1 \'Arial\'; }\n        .st-key-updated_live .health-copy span{ font:500 .57rem \'Arial\'; letter-spacing:.13em; color:var(--muted); text-transform:uppercase; }\n        .st-key-updated_live .state-line{ display:flex; align-items:center; justify-content:center; gap:.4rem; margin-top:.55rem; font:600 .65rem \'Arial\'; color:var(--state); letter-spacing:.08em; }\n        .st-key-updated_live .bus{ display:grid; grid-template-columns:120px repeat(10,minmax(0,1fr)); align-items:stretch; border:1px solid var(--line); background:#101214; margin:.7rem 0; overflow:hidden; }\n        .st-key-updated_live .bus-title{ padding:.58rem .68rem; border-right:1px solid var(--line); font:600 .58rem \'Arial\'; letter-spacing:.12em; color:var(--cyan); text-transform:uppercase; }\n        .st-key-updated_live .packet{ position:relative; overflow:hidden; padding:.48rem .35rem; border-right:1px solid rgba(55,59,63,.7); text-align:center; font:500 .52rem \'Arial\'; color:#989fa6; white-space:nowrap; }\n        .st-key-updated_live .packet:after{ content:\'\'; position:absolute; left:-45%; bottom:0; width:38%; height:2px; background:var(--packet); box-shadow:0 0 9px var(--packet); animation:packet 1.8s linear infinite; animation-delay:var(--delay); }\n        @keyframes packet { to { left:112%; } }\n        .st-key-updated_live .sensor-grid{ display:grid; grid-template-columns:repeat(5,1fr); gap:.52rem; }\n        .st-key-updated_live .sensor{ position:relative; min-height:74px; border:1px solid #2a2e33; background:rgba(11,12,13,.92); padding:.62rem .66rem; overflow:hidden; }\n        .st-key-updated_live .sensor:before{ content:\'\'; position:absolute; left:0; top:0; bottom:0; width:2px; background:var(--status); box-shadow:0 0 10px var(--status); }\n        .st-key-updated_live .sensor-name{ font:500 .56rem \'Arial\'; letter-spacing:.08em; color:#8e959c; text-transform:uppercase; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }\n        .st-key-updated_live .sensor-value{ margin:.22rem 0 .12rem; font:600 1.27rem/1 \'Arial\'; color:var(--ice); }\n        .st-key-updated_live .sensor-meta{ display:flex; justify-content:space-between; font:500 .54rem \'Arial\'; color:#707880; }\n        .st-key-updated_live .sensor-status{ color:var(--status); }\n        .st-key-updated_live .event{ border-left:2px solid var(--event); padding:.48rem .62rem; background:rgba(15,16,18,.78); margin:.4rem 0; }\n        .st-key-updated_live .event strong{ display:block; font:600 .65rem \'Arial\'; color:var(--event); }\n        .st-key-updated_live .event span{ font-size:.68rem; color:#979ea4; }\n        .st-key-updated_live .guard-alert{ display:flex; align-items:center; justify-content:space-between; gap:1rem; min-height:72px; margin:.1rem 0 .7rem; padding:.72rem 1rem; border:2px solid var(--red); background:linear-gradient(90deg,rgba(104,12,25,.97),rgba(38,8,17,.96)); box-shadow:0 0 28px rgba(217,121,95,.28),inset 0 0 28px rgba(217,121,95,.08); animation:guard-pulse 1.15s ease-in-out infinite alternate; }\n        .st-key-updated_live .guard-alert strong{ display:block; font:700 1.65rem/1 \'Arial\'; letter-spacing:.05em; color:#fff; }\n        .st-key-updated_live .guard-alert span{ display:block; margin-top:.25rem; font:500 .66rem \'Arial\'; color:#f0c4b6; letter-spacing:.04em; }\n        .st-key-updated_live .guard-alert .guard-mark{ flex:0 0 auto; font:700 1rem \'Arial\'; color:#fff; border:1px solid #f0c4b6; padding:.55rem .75rem; text-align:center; }\n        @keyframes guard-pulse { from { border-color:#d78b80; } .st-key-updated_live to{ border-color:#f0c4b6; box-shadow:0 0 42px rgba(217,121,95,.42),inset 0 0 30px rgba(217,121,95,.12); } }\n        .st-key-updated_live [data-testid="stToggle"]{ padding:.15rem .7rem .2rem; border-left:1px solid var(--line); }\n        .st-key-updated_live [data-testid="stToggle"] label p{ font:600 .69rem \'Arial\' !important; color:var(--cyan) !important; }\n        .st-key-updated_live div[data-testid="stPlotlyChart"]{ border:1px solid var(--line); background:rgba(8,9,10,.90); }\n        .st-key-updated_live .stProgress > div > div > div{ background:linear-gradient(90deg,var(--cyan),var(--mint)); }\n        .st-key-updated_live [data-testid="stProgressBar"]{ background:#232629; }\n        @media(max-width:900px) { .st-key-updated_live .sensor-grid{grid-template-columns:repeat(2,1fr)} .st-key-updated_live .bus{grid-template-columns:90px repeat(5,1fr)} .st-key-updated_live .packet:nth-child(n+7){display:none} .st-key-updated_live .kpi-grid{grid-template-columns:repeat(2,1fr)} }\n        @media(prefers-reduced-motion:reduce){ .live-dot,.packet:after,.guard-alert{animation:none!important} }\n</style>'

def render_live():
    st.markdown(LIVE_CSS, unsafe_allow_html=True)
    st.markdown("""<style>
    .st-key-updated_live [data-testid="stButton"] button p { white-space:normal; overflow:visible; font-size:.85rem; }
    .st-key-updated_live [data-testid="stToggle"] label p { white-space:normal; overflow:visible; }
    .st-key-updated_live { --line:#26292d; --ice:#f5f4ef; --muted:#9aa0a6; --cyan:#a9c4d4; --mint:#a1b3a2; }
    .st-key-updated_live .kpi, .st-key-updated_live .panel, .st-key-updated_live .sensor { background:#101214; border:1px solid #26292d; border-radius:9px; }
    .st-key-updated_live .kpi { padding:1rem; }
    .st-key-updated_live .k-label, .st-key-updated_live .k-note, .st-key-updated_live .sensor-name, .st-key-updated_live .sensor-meta, .st-key-updated_live .panel-label, .st-key-updated_live .state-line, .st-key-updated_live .clock span, .st-key-updated_live .event strong { font-size:.8rem; line-height:1.4; letter-spacing:.015em; text-transform:none; }
    .st-key-updated_live .sensor-name, .st-key-updated_live .sensor-meta, .st-key-updated_live .event span { color:#9aa0a6; white-space:normal; }
    .st-key-updated_live .sensor-value { font-size:1.45rem; margin:.45rem 0; }
    .st-key-updated_live .k-value { font-size:1.8rem; font-weight:600; }
    .st-key-updated_live .clock strong { font-size:1rem; }
    .st-key-updated_live .kpi:after, .st-key-updated_live .sensor:before, .st-key-updated_live .packet:after, .st-key-updated_live .live-dot { box-shadow:none; animation:none; }
    .st-key-updated_live .health-ring { filter:none; background:conic-gradient(var(--ring) calc(var(--score)*1%),#353630 0); }
    .st-key-updated_live .guard-alert { animation:none; box-shadow:none; background:#382420; border-color:#d78b80; border-radius:9px; }
    .st-key-updated_live .guard-alert strong { font-size:1.35rem; }
    .st-key-updated_live .guard-alert span, .st-key-updated_live .event span { font-size:.85rem; }
    .st-key-updated_live [data-testid="stButton"] button { border-radius:6px; background:#101214!important; border-color:#2a2e33!important; }
    .st-key-updated_live [data-testid="stToggle"] label p { font-size:.85rem!important; letter-spacing:0; }
    @media(max-width:900px) { .st-key-updated_live [data-testid="stHorizontalBlock"] { flex-wrap:wrap; } .st-key-updated_live [data-testid="stColumn"] { min-width:140px; } }
    @media(max-width:480px) { .st-key-updated_live .kpi-grid, .st-key-updated_live .sensor-grid { grid-template-columns:1fr; } .st-key-updated_live .k-value { overflow-wrap:normal; } }
    /* A fragment refresh must not fade its still-valid previous frame. */
    .st-key-updated_live [data-stale="true"] { opacity:1!important; }
    </style>""".replace("\n+", "\n"), unsafe_allow_html=True)
    with st.container(key="updated_live"):
        render(embedded=True)
